\section{Apa itu METs?}

\begin{frame}{Definisi dan Prinsip Dasar METs}
  \begin{definition}[METs]
    Sistem yang menggabungkan \textbf{degradasi mikroba} dengan \textbf{mekanisme elektrokimia} untuk mengubah polutan organik dalam air limbah menjadi energi listrik atau produk kimia bernilai.
  \end{definition}
  \vfill
  \begin{itemize}
    \item \textbf{Mikroorganisme Elektroaktif} (Eksoelektrogen) mendegradasi bahan organik.
    \item Menghasilkan \textbf{elektron} dan \textbf{proton}.
    \item Elektron mengalir melalui sirkuit eksternal $\rightarrow$ menghasilkan \textbf{listrik}.
    \item Proton berpindah melalui membran $\rightarrow$ melengkapi reaksi di katoda.
  \end{itemize}
\end{frame}

%% ========== SECTION 3: JENIS METs ==========
\section{Jenis-Jenis METs}

\begin{frame}{Ragam Teknologi METs}
  \begin{table}[]
    \centering
    \begin{tabular}{p{2cm} p{3.5cm} p{3cm}}
      \toprule
      \textbf{Metode} & \textbf{Produk Utama} & \textbf{Keunggulan Utama} \\
      \midrule
      \textbf{MFC} & Bio-listrik & Konversi limbah jadi energi, biaya rendah \\
      \textbf{MEC} & Bio-H$_2$, Metana & Modifikasi mudah, hasilkan gas mulia \\
      \textbf{MDC} & Air desalinasi + Listrik & Pengolahan \& desalinasi simultan \\
      \textbf{MES} & Asetat, Etanol, Butanol & Produksi bahan kimia industri \\
      \textbf{MCC} & Listrik + Biofuel (alga) & Serap CO$_2$, hasilkan biomassa \\
      \bottomrule
    \end{tabular}
  \end{table}
  \vfill
  \begin{center}
    \textit{MFC, MEC, dan MDC adalah yang paling banyak diteliti dan diterapkan.}
  \end{center}
\end{frame}

\begin{frame}{Skema Mekanisme MFC (Sistem Dasar)}
  \begin{columns}[T]
    \begin{column}{0.5\textwidth}
      \textbf{Kompartemen Anoda} (Anaerobic):
      \begin{itemize}
        \item Mikroba \textit{(Exoelectrogens)} oksidasi organik.
        \item Hasil: CO$_2$, H$^+$, dan e$^-$.
      \end{itemize}
      \vfill
      \textbf{Kompartemen Katoda} (Aerobic):
      \begin{itemize}
        \item Oksigen sebagai akseptor elektron.
        \item Reaksi: O$_2$ + 4H$^+$ + 4e$^-$ $\rightarrow$ 2H$_2$O.
      \end{itemize}
    \end{column}
    \begin{column}{0.5\textwidth}
      \begin{center}
        \fbox{\parbox{4cm}{\centering \textbf{ILUSTRASI MFC}\\ (Sirkuit Eksternal + PEM) \\ \vspace{0.5cm} \tiny Sumber: Das et al., 2021}}
      \end{center}
    \end{column}
  \end{columns}
\end{frame}

%% ========== SECTION 4: MIKROORGANISME ==========
\section{Mikroorganisme dalam METs}

\begin{frame}{Peran Mikroba: Kunci Keberhasilan METs}
  \begin{block}{Klasifikasi Berdasarkan Transfer Elektron}
    \begin{enumerate}
      \item \textbf{Eksoelektrogen}: Mentransfer elektron ke elektroda padat. \\
        \textit{Contoh: Geobacter sp., Shewanella sp., Pseudomonas sp.}
      \item \textbf{Elektrotrof}: Menerima elektron dari elektroda. \\
        \textit{Contoh: Sporomus ovata, Methanobacterium sp.}
    \end{enumerate}
  \end{block}
  \vfill
  \begin{alertblock}{Fakta Penting}
    \textit{Geobacter sp.} dapat menghasilkan rapat daya hingga \textbf{4.99 W/m$^2$} dan rapat arus \textbf{12.30 A/m$^2$}!
  \end{alertblock}
\end{frame}

%% ========== SECTION 5: FAKTOR KINERJA ==========
\section{Faktor yang Mempengaruhi Kinerja}

\begin{frame}{Faktor Fisikokimia yang Krusial}
  \begin{columns}[T]
    \begin{column}{0.5\textwidth}
      \textbf{1. Material Elektroda}
      \begin{itemize}
        \item Karbon (grafit, kertas karbon) lebih baik dari logam.
        \item Grafit felt memiliki luas permukaan tinggi.
      \end{itemize}
      \vfill
      \textbf{2. Membran Separator}
      \begin{itemize}
        \item Nafion umum digunakan, tetapi mahal.
        \item Alternatif murah: Keramik lempung, \textit{Biochar} tersulfonasi.
      \end{itemize}
    \end{column}
    \begin{column}{0.5\textwidth}
      \textbf{3. pH dan Suhu}
      \begin{itemize}
        \item pH netral (7) optimal untuk mikroba.
        \item Kenaikan suhu $24^\circ$C ke $35^\circ$C meningkatkan tegangan hingga 46\%.
      \end{itemize}
      \vfill
      \textbf{4. Salinitas}
      \begin{itemize}
        \item Meningkatkan konduktivitas, tetapi harus optimal (jangan terlalu tinggi).
      \end{itemize}
    \end{column}
  \end{columns}
\end{frame}

%% ========== SECTION 6: PRODUKSI BIOENERGI ==========
\section{Produksi Bioenergi}

\begin{frame}{Bioenergi yang Dihasilkan dari Limbah}
  \begin{itemize}
    \item \textbf{Produksi H$_2$ dan CH$_4$ (MEC)}:
      \begin{itemize}
        \item MEC menggunakan potensial eksternal kecil ($0.2$ V) untuk menghasilkan H$_2$.
        \item Produksi metana melalui \textit{electromethanogenesis}.
      \end{itemize}
    \vfill
    \item \textbf{Biofuel Cair (MCC dengan Alga)}:
      \begin{itemize}
        \item Mikroalga menangkap CO$_2$ dari anoda $\rightarrow$ tumbuh subur.
        \item Biomassa alga ($20-70\%$ lipid) diolah menjadi \textbf{biodiesel} dan \textbf{bioetanol}.
        \item Contoh: \textit{Chlorella vulgaris} menghasilkan lipid hingga 109 mg/L/hari.
      \end{itemize}
  \end{itemize}
\end{frame}

